"""Boss bodies: every boss is a creature of its own — never a grown-up monster. Three per kingdom (two by day, one by
night) on the same chibi skeleton and clips as the monsters (build_realm_beasts), built bigger in detail: crowns, armour,
wings, extra heads. The game scales them up ~3.4x.

    .venv/bin/python build_boss_beasts.py [out_dir] [--only scarecrow,hydra,...] [--size 512]

Copy <name>.glb to web/client/public/assets/.
"""
import math
import os
import sys

import build_beasts as bb
import build_realm_beasts as rb

WHITE, BLACK, DARK, PINK = bb.WHITE, bb.BLACK, bb.DARK, bb.PINK
spec, quills, bristle, limbs, eyes, big_eyes = rb.spec, rb.quills, rb.bristle, rb.limbs, bb.eyes, bb.big_eyes
HEAD, CORE, ARM, LEGS = rb.HEAD, rb.CORE, bb.ARMS[1:3], bb.ARMS[3:]
GOLD, GOLD_DK, STEEL, STEEL_DK = (0.90, 0.70, 0.24), (0.62, 0.44, 0.12), (0.62, 0.66, 0.72), (0.30, 0.32, 0.38)
B = {}
BUD = (3200, 3600, 1600, 900)


def wings(y=0.12, z=0.46, span=0.30, h=0.18, tilt=-15):
    """A pair of wings off the shoulder blades (the mirror adds the left): an inner and an outer lobe."""
    return [("ell", (0.14 + span * 0.35, y, z), (span * 0.45, 0.018, h), (0, 0, tilt)), ("ell", (0.14 + span * 0.85, y + 0.02, z + 0.06), (span * 0.35, 0.016, h * 0.8), (0, 0, tilt * 2))]


def crown(z=0.80, r=0.12, n=5, h=0.08, rad=0.018):
    """A band with points round the crown of the head."""
    return [("ell", (0, 0.0, z), (r, r * 0.9, 0.025), (0, 0, 0))] + [("cap", (math.cos(a) * r, math.sin(a) * r * 0.9, z), (math.cos(a) * r * 0.95, math.sin(a) * r * 0.85, z + h), rad)
                                                                    for a in [math.pi * (0.1 + 0.8 * i / (n - 1)) - math.pi / 2 for i in range(n)] if math.cos(a) >= -0.01]


